<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Point of Sale · AksiSoft POS</title>@vite(['resources/css/app.css', 'resources/js/app.js'])</head>
<body class="bg-slate-100">
<div class="min-h-screen" id="pos-app" data-store="{{ $store?->id }}" data-warehouse="{{ $warehouse?->id }}" data-session="{{ $session?->id }}">
    <header class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 bg-white px-4 py-3 lg:px-6"><div class="flex items-center gap-3"><a href="{{ route('dashboard') }}" class="flex h-9 w-9 items-center justify-center rounded-lg bg-[#172033] font-black text-white">A</a><div><h1 class="font-bold text-slate-900">Point of Sale</h1><p class="text-xs text-slate-500">{{ $store?->name }} · {{ $warehouse?->name }}</p></div></div><div class="flex items-center gap-2"><span class="badge {{ $session ? 'badge-success' : 'badge-warning' }}">{{ $session ? '● Register open' : '● Register closed' }}</span><span class="hidden text-sm text-slate-600 md:inline">{{ session('user_name') }}</span><a class="btn-secondary px-3 py-2" href="{{ route('dashboard') }}">Exit POS</a></div></header>
    <main class="grid gap-0 xl:grid-cols-[1fr_430px]">
        <section class="min-w-0 border-r border-slate-200 bg-slate-50 p-4 lg:p-6"><div class="mb-5 flex flex-col gap-3 sm:flex-row"><div class="relative flex-1"><input id="search" class="w-full py-3 pl-10 pr-4" placeholder="Scan barcode or search product (F1)" autofocus><span class="absolute left-3 top-3.5 text-slate-400">⌕</span></div><button id="shortcut-help" class="btn-secondary">Shortcuts</button></div><div class="mb-5 flex gap-2 overflow-x-auto pb-1"><button data-category="" class="category-filter rounded-full bg-indigo-600 px-4 py-2 text-sm font-semibold whitespace-nowrap text-white">All products</button>@foreach($categories as $category)<button data-category="{{ $category->id }}" class="category-filter rounded-full bg-white px-4 py-2 text-sm font-semibold whitespace-nowrap text-slate-600 ring-1 ring-slate-200 hover:bg-indigo-50">{{ $category->name }}</button>@endforeach</div><div id="product-grid" class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4">@foreach($products as $product)<button class="product-card card group p-3 text-left hover:border-indigo-300 hover:shadow-md" data-product='@json($product)'><div class="mb-3 flex h-24 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-50 to-slate-100 text-3xl font-black text-indigo-200">{{ strtoupper(mb_substr($product->name, 0, 1)) }}</div><p class="truncate text-sm font-bold text-slate-800">{{ $product->name }}</p><p class="mt-1 text-xs text-slate-500">{{ $product->sku }}</p><div class="mt-3 flex items-center justify-between gap-2"><p class="text-sm font-bold text-indigo-700">Rp{{ number_format($product->selling_price, 0, ',', '.') }}</p><span class="badge {{ $product->stock <= 0 ? 'badge-danger' : ($product->stock <= $product->low_stock_threshold ? 'badge-warning' : 'badge-success') }}">{{ number_format($product->stock, 0, ',', '.') }}</span></div></button>@endforeach</div><div id="empty-products" class="hidden py-16 text-center text-sm text-slate-400">No matching products were found.</div></section>
        <aside class="flex min-h-[calc(100vh-73px)] flex-col bg-white"><div class="border-b border-slate-100 p-5"><div class="flex items-center justify-between"><div><h2 class="font-bold text-slate-900">Current sale</h2><p class="text-xs text-slate-500">{{ $session ? 'Register session #'.$session->id : 'Open a register before checkout' }}</p></div><button id="clear-cart" class="text-sm font-semibold text-rose-600 hover:text-rose-700">Clear</button></div><div class="mt-4"><label class="field-label">Customer</label><select id="customer" class="w-full px-3 py-2"><option value="">Walk-in customer</option>@foreach($customers as $customer)<option value="{{ $customer->id }}">{{ $customer->name }}{{ $customer->phone ? ' · '.$customer->phone : '' }}</option>@endforeach</select></div></div><div id="cart-lines" class="flex-1 divide-y divide-slate-100 overflow-y-auto"><div id="empty-cart" class="p-10 text-center text-sm text-slate-400">Your cart is empty. Search or tap a product to start a sale.</div></div><div class="border-t border-slate-200 p-5"><div class="mb-3 flex items-center justify-between text-sm"><span class="text-slate-500">Subtotal</span><strong id="subtotal">Rp0</strong></div><div class="mb-3 flex items-center gap-2"><label class="w-20 text-sm text-slate-500">Discount</label><input id="discount" type="number" min="0" value="0" class="w-full px-3 py-2 text-right text-sm"><span class="text-xs text-slate-400">IDR</span></div><div class="mb-4 flex items-center justify-between border-t border-dashed border-slate-200 pt-4"><span class="font-bold text-slate-800">TOTAL</span><strong id="grand-total" class="text-2xl font-black text-indigo-700">Rp0</strong></div><div class="grid grid-cols-3 gap-2"><button data-method="cash" class="payment-method rounded-lg border-2 border-indigo-600 bg-indigo-50 px-2 py-2 text-sm font-bold text-indigo-700">Cash<br><span class="text-[10px] font-medium">F6</span></button><button data-method="qris" class="payment-method rounded-lg border border-slate-200 px-2 py-2 text-sm font-bold text-slate-600">QRIS<br><span class="text-[10px] font-medium">F7</span></button><button data-method="card" class="payment-method rounded-lg border border-slate-200 px-2 py-2 text-sm font-bold text-slate-600">Card<br><span class="text-[10px] font-medium">F8</span></button></div><label class="field-label mt-4">Cash received</label><input id="tendered" type="number" min="0" class="w-full px-3 py-2.5 text-right text-lg font-bold" value="0"><div class="mt-2 flex justify-between text-sm"><span class="text-slate-500">Change</span><strong id="change" class="text-emerald-600">Rp0</strong></div><button id="checkout" {{ $session ? '' : 'disabled' }} class="btn-primary mt-5 w-full py-3.5">Complete sale <span>F9</span></button><p id="pos-message" class="mt-3 text-center text-xs text-slate-500"></p></div></aside>
    </main>
</div>
<script>
const state={cart:[],method:'cash'}; const app=document.getElementById('pos-app'); const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID',{maximumFractionDigits:0});
function render(){const lines=document.getElementById('cart-lines'),empty=document.getElementById('empty-cart'); const subtotal=state.cart.reduce((t,x)=>t+x.quantity*x.selling_price,0), discount=Math.min(+document.getElementById('discount').value||0,subtotal), total=subtotal-discount, tendered=+document.getElementById('tendered').value||0; empty.classList.toggle('hidden',state.cart.length>0); [...lines.querySelectorAll('.cart-line')].forEach(n=>n.remove()); state.cart.forEach((item,i)=>{const el=document.createElement('div');el.className='cart-line p-4';el.innerHTML=`<div class="flex justify-between gap-3"><div class="min-w-0"><p class="truncate text-sm font-bold text-slate-800">${item.name}</p><p class="mt-1 text-xs text-slate-500">${item.sku} · ${money(item.selling_price)}</p></div><button class="remove text-rose-500" data-i="${i}">×</button></div><div class="mt-3 flex items-center justify-between"><div class="flex items-center rounded-lg border border-slate-200"><button class="qty px-3 py-1.5" data-i="${i}" data-d="-1">−</button><span class="min-w-10 text-center text-sm font-bold">${item.quantity}</span><button class="qty px-3 py-1.5" data-i="${i}" data-d="1">+</button></div><strong class="text-sm text-slate-900">${money(item.quantity*item.selling_price)}</strong></div>`;lines.append(el)});document.getElementById('subtotal').textContent=money(subtotal);document.getElementById('grand-total').textContent=money(total);document.getElementById('change').textContent=money(Math.max(0,tendered-total));document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{state.cart.splice(b.dataset.i,1);render()});document.querySelectorAll('.qty').forEach(b=>b.onclick=()=>{const x=state.cart[b.dataset.i];x.quantity+=+b.dataset.d;if(x.quantity<1)state.cart.splice(b.dataset.i,1);render()})}
function add(p){let item=state.cart.find(x=>x.id===p.id);if(item)item.quantity++;else state.cart.push({...p,quantity:1});render()}
document.querySelectorAll('.product-card').forEach(b=>b.onclick=()=>add(JSON.parse(b.dataset.product))); document.getElementById('clear-cart').onclick=()=>{state.cart=[];render()};document.querySelectorAll('.payment-method').forEach(b=>b.onclick=()=>{state.method=b.dataset.method;document.querySelectorAll('.payment-method').forEach(x=>x.className='payment-method rounded-lg border border-slate-200 px-2 py-2 text-sm font-bold text-slate-600');b.className='payment-method rounded-lg border-2 border-indigo-600 bg-indigo-50 px-2 py-2 text-sm font-bold text-indigo-700'});document.getElementById('discount').oninput=render;document.getElementById('tendered').oninput=render;
let timer;document.getElementById('search').oninput=e=>{clearTimeout(timer);timer=setTimeout(async()=>{const r=await fetch(`/api/v1/products/search?q=${encodeURIComponent(e.target.value)}&warehouse_id=${app.dataset.warehouse}`);const list=await r.json();const grid=document.getElementById('product-grid');grid.innerHTML='';list.forEach(p=>{const b=document.createElement('button');b.className='product-card card p-3 text-left hover:border-indigo-300';b.innerHTML=`<div class="mb-3 flex h-24 items-center justify-center rounded-lg bg-indigo-50 text-3xl font-black text-indigo-200">${p.name[0]}</div><p class="truncate text-sm font-bold">${p.name}</p><p class="mt-1 text-xs text-slate-500">${p.sku}</p><div class="mt-3 flex justify-between"><b class="text-sm text-indigo-700">${money(p.selling_price)}</b><span class="text-xs">Stock ${Number(p.stock)}</span></div>`;b.onclick=()=>add(p);grid.append(b)});document.getElementById('empty-products').classList.toggle('hidden',list.length>0)},220)};
document.getElementById('checkout').onclick=async()=>{const msg=document.getElementById('pos-message');if(!state.cart.length)return msg.textContent='Add at least one item.';const total=state.cart.reduce((t,x)=>t+x.quantity*x.selling_price,0)-(+document.getElementById('discount').value||0);if(+document.getElementById('tendered').value<total)return msg.textContent='Payment amount is less than total.';msg.textContent='Completing sale…';const r=await fetch('/api/v1/sales/checkout',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({store_id:+app.dataset.store,warehouse_id:+app.dataset.warehouse,register_session_id:app.dataset.session?+app.dataset.session:null,customer_id:document.getElementById('customer').value||null,discount_total:+document.getElementById('discount').value||0,payment_method:state.method,tendered_amount:+document.getElementById('tendered').value,items:state.cart.map(x=>({product_id:x.id,quantity:x.quantity,unit_price:x.selling_price}))})});const d=await r.json();if(!r.ok){msg.textContent=d.message||Object.values(d.errors||{}).flat()[0]||'Checkout failed.';return}window.open(d.receipt_url,'_blank');state.cart=[];document.getElementById('discount').value=0;document.getElementById('tendered').value=0;render();msg.textContent=`Sale ${d.invoice_number} completed. Receipt opened.`};
document.addEventListener('keydown',e=>{if(e.key==='F1'){e.preventDefault();document.getElementById('search').focus()}if(e.key==='F9'){e.preventDefault();document.getElementById('checkout').click()}if(e.key==='Escape'){document.getElementById('search').value=''}});document.getElementById('shortcut-help').onclick=()=>alert('F1 Search · F6 Cash · F7 QRIS · F8 Card · F9 Complete Sale · ESC Clear search');render();
</script>
</body></html>
